const pane=$('workspace_connections'),card=add(pane,'section',undefined,'card connection-card gmail-card');pane.querySelector('section')?.after(card);
add(card,'p','MAIL THAT CONNECTS TO YOUR LIFE','eyebrow');add(card,'h2','Gmail context');add(card,'p','Find real invitations, events, opportunities and things that need time. Choose the emails WAM can use, then review the details. Nothing is sent, booked or bought.');
