const connect=button(actions,'Connect Gmail (read-only)',connectMail),refresh=button(actions,'Refresh recent emails',loadMail),disconnect=button(actions,'Disconnect Google apps & clear fetched data',()=>M.disconnect());refresh.disabled=disconnect.disabled=true;
